+            REQUIRE_FALSE(script.empty());
+            reply = script.front();
+            script.pop_front();
+            replies.push_back(request.body);
+        }
+        event(AgentHttpEvent{AgentHttpEvent::Kind::Data, m_wire.stream(reply, std::to_string(++m_responses)), {}, 0});
